"""Typed model objects, values, and the predicate expression AST.

A campaign names every type once; `build_types` resolves the (possibly forward
referencing, always acyclic) graph into `Type` objects.  Predicates arrive as
typed JSON expression arrays and are compiled once into Python closures that
evaluate a lexical environment of module inputs and `all` bindings.
"""
from .errors import InvalidCampaign
from .regex import compile_pattern

MAX_NAME = 32
MAX_DEPTH = 64


def _need(condition, message):
    if not condition:
        raise InvalidCampaign(message)


def _integer(value):
    if type(value) is not int:
        raise InvalidCampaign("expected an integer")
    return value


def _identifier(value):
    if not isinstance(value, str) or not value:
        raise InvalidCampaign("expected an identifier")
    if len(value) > MAX_NAME:
        raise InvalidCampaign("identifier too long")
    head = value[0]
    if not (head.isalpha() and head.isascii() or head == "_"):
        raise InvalidCampaign("invalid identifier")
    for char in value[1:]:
        if not (char.isalnum() and char.isascii() or char == "_"):
            raise InvalidCampaign("invalid identifier")
    return value


# --------------------------------------------------------------------------
# Types
# --------------------------------------------------------------------------


class Type(object):
    """Base class of the Eywa type lattice."""

    decl = None

    @staticmethod
    def inner(type):
        """Look past any type aliases to get the inner type."""
        while isinstance(type, Alias):
            type = type.type
        return type


class Void(Type):
    """No value at all."""


class Bool(Type):
    """True or false."""


class Char(Type):
    """One Latin-1 character, including NUL."""


class Int(Type):
    """An unsigned integer of at most `bits` bits."""

    def __init__(self, bits: int = 32):
        self.bits = bits

    @property
    def width(self) -> int:
        bits = self.bits
        if bits <= 8:
            return 1
        if bits <= 16:
            return 2
        if bits <= 32:
            return 4
        return 8

    @property
    def limit(self) -> int:
        return 1 << self.bits


class String(Type):
    """A bounded Latin-1 C string."""

    def __init__(self, maxsize: int = 0):
        if maxsize < 0:
            raise InvalidCampaign("invalid string type")
        self.maxsize = maxsize
        self.char_type = Char()


class Enum(Type):
    """One of a fixed list of strings."""

    def __init__(self, name: str, values):
        self.name = name
        self.values = list(values)

    @property
    def width(self) -> int:
        return 4


class Array(Type):
    """An ordered fixed-length list."""

    def __init__(self, element_type: Type, size: int):
        self.element_type = element_type
        self.size = size


class Struct(Type):
    """A record with an ordered field list."""

    def __init__(self, name: str, fields=None):
        self.name = name
        self.fields = dict(fields) if fields else {}


class Alias(Type):
    """A transparent value and layout alias."""

    def __init__(self, name: str, type: Type, description=None):
        self.name = name
        self.type = type
        self.description = description


def underlying(type: Type) -> Type:
    """Strip aliases; declarations keep their name but values do not."""
    while isinstance(type, Alias):
        type = type.type
    return type


def int_width(bits: int) -> int:
    if bits <= 8:
        return 1
    if bits <= 16:
        return 2
    if bits <= 32:
        return 4
    return 8


def canonical_value(type: Type, value):
    """Validate a JSON value against a type and normalise it.

    No truncation or padding is applied: string constants keep embedded NULs,
    which makes them distinct from the value recovered from a symbolic string
    object of the same bytes.
    """
    base = underlying(type)
    if isinstance(base, Bool):
        _need(type(value) is bool, "boolean value expected")
        return value
    if isinstance(base, Char):
        _need(isinstance(value, str) and len(value) == 1
              and 0 <= ord(value) <= 255, "character value expected")
        return value
    if isinstance(base, Int):
        _need(type(value) is int and 0 <= value < base.limit,
              "integer value out of range")
        return value
    if isinstance(base, String):
        _need(isinstance(value, str) and len(value) <= base.maxsize,
              "string constant too long")
        for char in value:
            _need(0 <= ord(char) <= 255, "string constant must be Latin-1")
        return value
    if isinstance(base, Enum):
        _need(isinstance(value, str) and value in base.values,
              "enum value expected")
        return value
    if isinstance(base, Array):
        _need(isinstance(value, list) and len(value) == base.size,
              "array value expected")
        return [canonical_value(base.element_type, item) for item in value]
    if isinstance(base, Struct):
        _need(isinstance(value, dict) and set(value.keys()) == set(base.fields),
              "struct value expected")
        return {field: canonical_value(ftype, value[field])
                for field, ftype in base.fields.items()}
    if isinstance(base, Void):
        _need(value is None, "void has no value")
        return None
    raise InvalidCampaign("unsupported type")


def deep_equal(left, right) -> bool:
    """Deep, type strict comparison used by `eq` and `ne`."""
    if left is right:
        return True
    kind = type(left)
    if kind is not type(right):
        return False
    if kind is bool or kind is int or kind is str:
        return left == right
    if kind is list:
        if len(left) != len(right):
            return False
        for one, two in zip(left, right):
            if not deep_equal(one, two):
                return False
        return True
    if kind is dict:
        if left.keys() != right.keys():
            return False
        for key in left:
            if not deep_equal(left[key], right[key]):
                return False
        return True
    return left == right


# --------------------------------------------------------------------------
# Type table
# --------------------------------------------------------------------------


def build_types(definitions) -> dict:
    """Resolve the declared type list into a name -> Type table."""
    if not isinstance(definitions, list):
        raise InvalidCampaign("types must be a list")
    table = {}
    shells = []
    for definition in definitions:
        _need(isinstance(definition, dict), "type definition must be an object")
        name = _identifier(definition.get("name"))
        kind = definition.get("kind")
        _need(isinstance(kind, str), "type kind must be a string")
        _need(name not in table, "duplicate type name")
        if kind == "bool":
            type = Bool()
        elif kind == "char":
            type = Char()
        elif kind == "int":
            bits = _integer(definition.get("bits"))
            _need(1 <= bits <= 64, "int bits out of range")
            type = Int(bits)
        elif kind == "string":
            maxsize = _integer(definition.get("maxsize"))
            _need(0 <= maxsize <= 512, "string maxsize out of range")
            type = String(maxsize)
        elif kind == "enum":
            values = definition.get("values")
            _need(isinstance(values, list) and values, "enum values expected")
            for value in values:
                _need(isinstance(value, str) and value and value.isascii()
                      and value.isprintable() and len(value) <= 64,
                      "enum value must be printable ASCII")
            _need(len(set(values)) == len(values), "duplicate enum value")
            type = Enum(name, values)
        elif kind == "array":
            size = _integer(definition.get("size"))
            _need(0 <= size <= 4096, "array size out of range")
            type = Array(None, size)
        elif kind == "struct":
            fields = definition.get("fields")
            _need(isinstance(fields, list), "struct fields expected")
            type = Struct(name)
            shells.append((type, fields))
            table[name] = type
            type.decl = name
            continue
        elif kind == "alias":
            type = Alias(name, None)
            shells.append((type, definition.get("target")))
            table[name] = type
            type.decl = name
            continue
        elif kind == "void":
            type = Void()
        else:
            raise InvalidCampaign("unknown type kind")
        table[name] = type
        type.decl = name
    # Second pass links forward references.
    for type, payload in shells:
        if isinstance(type, Struct):
            _need(isinstance(payload, list), "struct fields must be a list")
            fields = {}
            for entry in payload:
                _need(isinstance(entry, list) and len(entry) == 2,
                      "struct field pair expected")
                field = _identifier(entry[0])
                target = entry[1]
                _need(isinstance(target, str), "field type name expected")
                _need(field not in fields, "duplicate struct field")
                fields[field] = target
            _need(len(fields) <= 16, "too many struct fields")
            type.fields = fields
        else:
            target = payload
            _need(isinstance(target, str), "alias target expected")
            _need(target in table, "unknown alias target")
            target_type = table[target]
            _need(not isinstance(target_type, Void), "alias to void")
            type.type = target_type
    for type in table.values():
        if isinstance(type, Array):
            element = definition_of(table, type)
    _link_arrays(table, definitions)
    _check_acyclic(table)
    return table


def _link_arrays(table, definitions):
    for definition in definitions:
        if definition.get("kind") != "array":
            continue
        name = definition.get("name")
        type = table[name]
        element = definition.get("element")
        _need(isinstance(element, str), "array element type expected")
        _need(element in table, "unknown array element type")
        _need(not isinstance(table[element], Void), "array of void")
        type.element_type = table[element]


def definition_of(table, type):
    raise InvalidCampaign("unreachable")


def _check_acyclic(table):
    state = {}
    for name in table:
        stack = [name]
        seen = set()
        while stack:
            current = stack.pop()
            if current in seen:
                continue
            seen.add(current)
            type = table[current]
            if isinstance(type, Alias):
                stack.append(type.type.decl)
            elif isinstance(type, Array):
                stack.append(type.element_type.decl)
            elif isinstance(type, Struct):
                for target in type.fields.values():
                    stack.append(target)
        state[name] = seen
    for name, seen in state.items():
        _need(name not in seen or len(seen) == 1, "cyclic type graph")
    # A cycle shows up as a type whose closure contains itself plus others.
    for name, seen in state.items():
        if len(seen) > 1 and name in seen:
            raise InvalidCampaign("cyclic type graph")


# --------------------------------------------------------------------------
# Modules
# --------------------------------------------------------------------------


class Module(object):
    """A model: ordered inputs, one result, and an optional requirement."""

    __slots__ = ("name", "params", "result", "requires", "scope")

    def __init__(self, name, params, result, requires, scope):
        self.name = name
        self.params = params          # list of (name, Type)
        self.result = result          # (name, Type)
        self.requires = requires      # callable or None
        self.scope = scope            # name -> Type


def build_modules(definitions, table) -> dict:
    if not isinstance(definitions, list):
        raise InvalidCampaign("modules must be a list")
    modules = {}
    for definition in definitions:
        _need(isinstance(definition, dict), "module must be an object")
        name = _identifier(definition.get("name"))
        _need(name not in modules, "duplicate module name")
        raw_params = definition.get("params")
        _need(isinstance(raw_params, list), "module params must be a list")
        _need(len(raw_params) <= 16, "too many module parameters")
        params = []
        scope = {}
        for entry in raw_params:
            _need(isinstance(entry, list) and len(entry) == 2,
                  "parameter pair expected")
            pname = _identifier(entry[0])
            tname = entry[1]
            _need(isinstance(tname, str) and tname in table, "unknown parameter type")
            _need(pname not in scope, "duplicate parameter name")
            scope[pname] = table[tname]
            params.append((pname, table[tname]))
        raw_result = definition.get("result")
        _need(isinstance(raw_result, list) and len(raw_result) == 2,
              "module result pair expected")
        rname = _identifier(raw_result[0])
        rtname = raw_result[1]
        _need(isinstance(rtname, str) and rtname in table, "unknown result type")
        result_type = table[rtname]
        _need(isinstance(result_type, Void) or not isinstance(underlying(result_type), Void)
              or True, "result type")
        if isinstance(underlying(result_type), Void):
            pass
        _need(rname not in scope, "result name collides with a parameter")
        requires = definition.get("requires")
        predicate = None
        if requires is not None:
            predicate = compile_predicate(requires, scope, table)
        modules[name] = Module(name, params, (rname, result_type), predicate, scope)
    return modules


# --------------------------------------------------------------------------
# Predicate expressions
# --------------------------------------------------------------------------

_FORMS = ("var", "const", "field", "index", "all", "match", "not")
_BINARY = ("eq", "ne", "lt", "le", "gt", "ge", "add", "sub",
           "and", "or", "implies")
_MISSING = object()


def compile_predicate(source, scope, table):
    """Compile a predicate into `fn(env) -> bool`; `null` means true."""
    if source is None:
        return None
    fn, kind = _compile(source, scope, table, 0)
    _need(kind is not None and isinstance(underlying(kind), Bool),
          "predicate must be boolean")
    return fn


def _compile(source, scope, table, depth):
    if depth > MAX_DEPTH:
        raise InvalidCampaign("expression too deep")
    _need(isinstance(source, list) and source, "expression must be an array")
    form = source[0]
    if isinstance(form, str) and form in _FORMS:
        return _compile_form(form, source, scope, table, depth)
    _need(isinstance(form, str) and form in _BINARY, "unknown operator")
    _need(len(source) == 3, "binary operation arity")
    left, ltype = _compile(source[1], scope, table, depth + 1)
    right, rtype = _compile(source[2], scope, table, depth + 1)
    return _compile_binary(form, left, ltype, right, rtype)


def _compile_form(form, source, scope, table, depth):
    if form == "var":
        _need(len(source) == 2, "var arity")
        name = source[1]
        _need(isinstance(name, str), "variable name expected")
        _need(name in scope, "unbound variable " + name)
        def fn(env, name=name):
            return env[name]
        return fn, scope[name]

    if form == "const":
        _need(len(source) == 3, "const arity")
        tname = source[1]
        _need(isinstance(tname, str) and tname in table, "unknown const type")
        type = table[tname]
        value = canonical_value(type, source[2])
        def fn(env, value=value):
            return value
        return fn, type

    if form == "field":
        _need(len(source) == 3, "field arity")
        inner, itype = _compile(source[1], scope, table, depth + 1)
        field = source[2]
        base = underlying(itype)
        _need(isinstance(base, Struct), "field expects a struct")
        _need(isinstance(field, str) and field in base.fields,
              "unknown struct field")
        ftype = base.fields[field]
        def fn(env, inner=inner, field=field):
            return inner(env)[field]
        return fn, ftype

    if form == "index":
        _need(len(source) == 3, "index arity")
        inner, itype = _compile(source[1], scope, table, depth + 1)
        index, itype2 = _compile(source[2], scope, table, depth + 1)
        base = underlying(itype)
        _need(isinstance(base, Array), "index expects an array")
        _need(isinstance(underlying(itype2), Int), "index must be an integer")
        etype = base.element_type
        def fn(env, inner=inner, index=index):
            return inner(env)[index(env)]
        return fn, etype

    if form == "all":
        _need(len(source) == 4, "all arity")
        binding = source[1]
        _need(isinstance(binding, str), "binding name expected")
        array_fn, atype = _compile(source[2], scope, table, depth + 1)
        base = underlying(atype)
        _need(isinstance(base, Array), "all expects an array")
        inner_scope = dict(scope)
        inner_scope[binding] = base.element_type
        body, _ = _compile(source[3], inner_scope, table, depth + 1)
        def fn(env, array_fn=array_fn, body=body, binding=binding):
            for element in array_fn(env):
                previous = env.get(binding, _MISSING)
                env[binding] = element
                try:
                    if not body(env):
                        return False
                finally:
                    if previous is _MISSING:
                        env.pop(binding, None)
                    else:
                        env[binding] = previous
            return True
        return fn, Bool()

    if form == "match":
        _need(len(source) == 3, "match arity")
        inner, itype = _compile(source[1], scope, table, depth + 1)
        _need(isinstance(underlying(itype), String), "match expects a string")
        pattern = source[2]
        _need(isinstance(pattern, str) and len(pattern) <= 128,
              "pattern expected")
        compiled = compile_pattern(pattern)
        def fn(env, inner=inner, compiled=compiled):
            return compiled.matches(inner(env))
        return fn, Bool()

    if form == "not":
        _need(len(source) == 2, "not arity")
        inner, _ = _compile(source[1], scope, table, depth + 1)
        def fn(env, inner=inner):
            return not inner(env)
        return fn, Bool()

    raise InvalidCampaign("unsupported expression form")


def _compile_binary(op, left, ltype, right, rtype):
    if op in ("and", "or", "implies"):
        if op == "and":
            def fn(env, left=left, right=right):
                return left(env) and right(env)
        elif op == "or":
            def fn(env, left=left, right=right):
                return left(env) or right(env)
        else:
            def fn(env, left=left, right=right):
                return (not left(env)) or right(env)
        return fn, Bool()

    if op in ("eq", "ne"):
        negate = op == "ne"
        def fn(env, left=left, right=right, negate=negate):
            result = deep_equal(left(env), right(env))
            return result != negate
        return fn, Bool()

    if op in ("lt", "le", "gt", "ge"):
        _need(isinstance(underlying(ltype), Int), "comparison expects integers")
        _need(isinstance(underlying(rtype), Int), "comparison expects integers")
        if op == "lt":
            compare = lambda a, b: a < b
        elif op == "le":
            compare = lambda a, b: a <= b
        elif op == "gt":
            compare = lambda a, b: a > b
        else:
            compare = lambda a, b: a >= b
        def fn(env, left=left, right=right, compare=compare):
            return compare(left(env), right(env))
        return fn, Bool()

    if op in ("add", "sub"):
        lbase = underlying(ltype)
        rbase = underlying(rtype)
        _need(isinstance(lbase, Int), "arithmetic expects integers")
        _need(isinstance(rbase, Int), "arithmetic expects integers")
        mask = (1 << lbase.bits) - 1
        subtract = op == "sub"
        def fn(env, left=left, right=right, mask=mask, subtract=subtract):
            one = left(env)
            two = right(env)
            return (one - two if subtract else one + two) & mask
        return fn, ltype

    raise InvalidCampaign("unknown binary operator")


class Evaluator(object):
    """Evaluate a compiled predicate against a variable assignment."""

    def __init__(self, assignment):
        self.assignment = assignment

    def __call__(self, predicate):
        if predicate is None:
            return True
        return bool(predicate(self.assignment))


class Expr(object):
    """Compatibility shim: evaluates a compiled predicate closure."""

    def __init__(self, fn, type):
        self.fn = fn
        self.type = type

    def eval(self, assignment):
        return self.fn(assignment)


class Parameter(object):
    """A named, typed model input."""

    def __init__(self, name: str, type: Type, description=None):
        self.name = name
        self.type = type
        self.description = description


class Function(object):
    """A model described by parameters, one result, and a requirement."""

    def __init__(self, name: str, params, result, requires=None, scope=None):
        self.name = name
        self.params = params
        self.result = result
        self.requires = requires
        self.scope = scope if scope is not None else {}
